// agentic-skills-hooks plugin (generated by agentic-skills; remove it with the uninstaller)
// Forwards OpenCode events to the agentic-skills hooks jar as Claude-Code-shaped JSON on stdin.
import { spawn, spawnSync } from "node:child_process"

const JAR = "__AGENTIC_SKILLS_HOOKS_JAR__"
const GUARD = __AGENTIC_SKILLS_GUARD__

const TOOL_NAMES = { bash: "Bash", read: "Read", edit: "Edit", write: "Write" }
const toolName = (t) => TOOL_NAMES[t] || t

// Fire-and-forget: analytics must never throw or block OpenCode.
function fire(hookType, payload) {
  try {
    const child = spawn("java", ["-jar", JAR, hookType], { stdio: ["pipe", "ignore", "ignore"] })
    child.on("error", () => {})
    child.stdin.on("error", () => {})
    child.stdin.end(JSON.stringify(payload))
    child.unref()
  } catch (_) {
    // ignore
  }
}

export const AgenticSkillsHooks = async ({ directory }) => {
  const cwd = directory || process.cwd()
  const base = (event, sessionId) => ({ hook_event_name: event, session_id: sessionId || "", cwd })
  // tool.execute.before carries the args; remember them for the matching after event.
  const pendingArgs = new Map()

  return {
    "tool.execute.before": async (input, output) => {
      const args = (output && output.args) || {}
      if (input && input.callID) pendingArgs.set(input.callID, args)
      if (!GUARD) return
      let result
      try {
        result = spawnSync("java", ["-jar", JAR, "guard"], {
          input: JSON.stringify({
            ...base("PreToolUse", input.sessionID),
            tool_name: toolName(input.tool),
            tool_input: args,
          }),
          encoding: "utf8",
          timeout: 10000,
        })
      } catch (_) {
        return // failing to run the guard must not block the user
      }
      if (result && result.status === 2) {
        throw new Error((result.stderr || "Blocked by agentic-skills guard").trim())
      }
    },

    "tool.execute.after": async (input) => {
      try {
        const args = (input && input.args) || pendingArgs.get(input && input.callID) || {}
        if (input && input.callID) pendingArgs.delete(input.callID)
        fire("post-tool-use", {
          ...base("PostToolUse", input.sessionID),
          tool_name: toolName(input.tool),
          tool_input: args,
        })
      } catch (_) {
        // ignore
      }
    },

    event: async ({ event }) => {
      try {
        const props = (event && event.properties) || {}
        const sid = props.sessionID || (props.info && props.info.id) || ""
        if (event.type === "session.created") {
          fire("session", { ...base("SessionStart", sid), source: "startup" })
        } else if (event.type === "session.idle") {
          fire("stop", base("Stop", sid))
        } else if (event.type === "session.deleted") {
          fire("session", { ...base("SessionEnd", sid), reason: "other" })
        }
      } catch (_) {
        // ignore
      }
    },
  }
}
